const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], q = tok[1];
const xs = [], ys = [];
for (let i = 0; i < n; i++) { xs.push(tok[2 + 2 * i]); ys.push(tok[3 + 2 * i]); }
let pos = 2 + 2 * n;
const out = [];
for (let k = 0; k < q; k++) {
  const px = tok[pos], py = tok[pos + 1];
  pos += 2;
  let inside = false, onEdge = false;
  for (let i = 0; i < n; i++) {
    const x1 = xs[i], y1 = ys[i], x2 = xs[(i + 1) % n], y2 = ys[(i + 1) % n];
    const cross = (x2 - x1) * (py - y1) - (px - x1) * (y2 - y1);
    if (cross === 0 && Math.min(x1, x2) <= px && px <= Math.max(x1, x2) && Math.min(y1, y2) <= py && py <= Math.max(y1, y2)) { onEdge = true; break; }
    if ((y1 > py) !== (y2 > py)) {
      if (y2 > y1) { if (cross > 0) inside = !inside; }
      else if (cross < 0) inside = !inside;
    }
  }
  out.push(onEdge ? "BOUNDARY" : (inside ? "INSIDE" : "OUTSIDE"));
}
console.log(out.join("\n"));

