import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        long[] xs = new long[n], ys = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); xs[i] = (long) in.nval;
            in.nextToken(); ys[i] = (long) in.nval;
        }
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            in.nextToken(); long px = (long) in.nval;
            in.nextToken(); long py = (long) in.nval;
            boolean inside = false, onEdge = false;
            for (int i = 0; i < n; i++) {
                long x1 = xs[i], y1 = ys[i], x2 = xs[(i + 1) % n], y2 = ys[(i + 1) % n];
                long cross = (x2 - x1) * (py - y1) - (px - x1) * (y2 - y1);
                if (cross == 0 && Math.min(x1, x2) <= px && px <= Math.max(x1, x2) && Math.min(y1, y2) <= py && py <= Math.max(y1, y2)) { onEdge = true; break; }
                if ((y1 > py) != (y2 > py)) {
                    if (y2 > y1) { if (cross > 0) inside = !inside; }
                    else if (cross < 0) inside = !inside;
                }
            }
            out.append(onEdge ? "BOUNDARY" : (inside ? "INSIDE" : "OUTSIDE")).append('\n');
        }
        System.out.print(out);
    }
}

