#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    vector<ll> xs(n), ys(n);
    for (int i = 0; i < n; i++) scanf("%lld %lld", &xs[i], &ys[i]);
    while (q--) {
        ll px, py;
        scanf("%lld %lld", &px, &py);
        bool inside = false, onEdge = false;
        for (int i = 0; i < n; i++) {
            ll x1 = xs[i], y1 = ys[i], x2 = xs[(i + 1) % n], y2 = ys[(i + 1) % n];
            ll cross = (x2 - x1) * (py - y1) - (px - x1) * (y2 - y1);
            if (cross == 0 && min(x1, x2) <= px && px <= max(x1, x2) && min(y1, y2) <= py && py <= max(y1, y2)) { onEdge = true; break; }
            if ((y1 > py) != (y2 > py)) {
                if (y2 > y1) { if (cross > 0) inside = !inside; }
                else if (cross < 0) inside = !inside;
            }
        }
        puts(onEdge ? "BOUNDARY" : (inside ? "INSIDE" : "OUTSIDE"));
    }
    return 0;
}
